"""Validate exact 24/25/26 patch stacks and migrate reviewed caches only."""
import hashlib,json,pathlib,re,shutil,subprocess,tempfile
from mesa_patch_identity import validate_recorded_patches
HERE=pathlib.Path(__file__).resolve().parent
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def ensure(root,source,pins):
 root=pathlib.Path(root).resolve();source=pathlib.Path(source).resolve()
 m=json.loads((HERE/"data/mesa-reviewed-fixes.json").read_text(encoding="utf-8"))
 c=json.loads((HERE/"data/mesa160-fixes.json").read_text(encoding="utf-8"))
 if subprocess.check_output(["git","-C",str(source),"rev-parse","HEAD"],text=True).strip()!=m["mesa"]:raise ValueError("Mesa pin differs")
 if subprocess.check_output(["git","-C",str(source),"rev-parse","HEAD^{tree}"],text=True).strip()!=m["mesa_tree"]:raise ValueError("Mesa tree differs")
 expected=[p["upstream"] for p in m["ordered_existing_overlays"]]+[m["new_patch"],c["new_patch"]]
 if pins["mesa"]["commit"]!=m["mesa"] or pins["mesa"]["tree"]!=m["mesa_tree"] or pins["patches"]!=expected:raise ValueError("Mesa recorded identity/order differs")
 for p in m["ordered_existing_overlays"]+[{"upstream":m["new_patch"],"sha256":m["patch_sha256"]},{"upstream":c["new_patch"],"sha256":c["patch_sha256"]}]:
  if digest(root/p["upstream"])!=p["sha256"]:raise ValueError("Mesa patch differs: "+p["upstream"])
 final={f["path"]:f["after_sha256"] for f in m["files"]};final.update({f["path"]:f["after_sha256"] for f in c["files"]})
 def hashes_match(rows,key):return all((source/f["path"]).is_file() and digest(source/f["path"])==f[key] for f in rows)
 if hashes_match(c["files"],"after_sha256"):
  old_count=26
 elif hashes_match(c["files"],"before_sha256") and hashes_match(m["files"],"after_sha256"):
  old_count=25
 elif hashes_match(m["files"],"before_sha256"):
  old_count=24
 else:raise ValueError("Mesa partial/unknown cache state")
 # Reverse the entire recognized stack to HEAD, including every touched file;
 # this rejects outside edits and same-file edits outside the manifest subset.
 validate_recorded_patches(root,source,dict(pins,patches=expected[:old_count]))
 paths=set(final)
 for name in expected:
  paths.update(re.findall(r"^diff --git a/(\S+) b/\1$",(root/name).read_text(encoding="utf-8"),re.M))
 before={p:(source/p).read_bytes() if (source/p).is_file() else None for p in paths}
 with tempfile.TemporaryDirectory(prefix="mesa160-stage-",dir=root/".cache") as name:
  stage=pathlib.Path(name)
  for p,b in before.items():
   if b is not None:q=stage/p;q.parent.mkdir(parents=True,exist_ok=True);q.write_bytes(b)
  for patch in expected[old_count:]:
   subprocess.run(["git","-c","core.autocrlf=false","apply","--check",str(root/patch)],cwd=stage,check=True,capture_output=True)
   subprocess.run(["git","-c","core.autocrlf=false","apply",str(root/patch)],cwd=stage,check=True,capture_output=True)
  if any(not (stage/p).is_file() or digest(stage/p)!=h for p,h in final.items()):raise ValueError("Mesa staged output identity differs")
  for p,b in before.items():
   now=(source/p).read_bytes() if (source/p).is_file() else None
   if now!=b:raise ValueError("Mesa source changed during staging: "+p)
  # Validate all outputs before writing; no claim of an atomic filesystem transaction.
  if old_count!=26:
   for p in paths:
    q=stage/p
    if q.is_file() and q.read_bytes()!=before[p]:(source/p).parent.mkdir(parents=True,exist_ok=True);(source/p).write_bytes(q.read_bytes())
 validate_recorded_patches(root,source,pins)
 actual={p:digest(source/p) for p in final}
 if actual!=final:raise ValueError("Mesa final output identity differs")
 report={"mesa":m["mesa"],"mesa_tree":m["mesa_tree"],"patch_count":26,"semantic_backports":185,"previous_patch_count":old_count,"reviewed_patch_sha256":m["patch_sha256"],"compound_patch_sha256":c["patch_sha256"],"migrated_old_cache":old_count!=26,"source_sha256":actual,"compound_source_sha256":{f["path"]:actual[f["path"]] for f in c["files"]},"freedreno_commits":m["freedreno_commits"],"nir_commits":m["nir_commits"],"compound_commits":c["commits"]}
 out=root/"build/mesa-reviewed-source.json";out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(report,indent=2),encoding="utf-8")
 return report

